import{_ as a,o as l,c as t,a2 as i}from"./chunks/framework.ClgMjOt7.js";const h=JSON.parse('{"title":"ユーザーガイド","description":"Palleria の特徴、画面構成、主な機能ガイド","frontmatter":{"title":"ユーザーガイド","description":"Palleria の特徴、画面構成、主な機能ガイド"},"headers":[],"relativePath":"user/index.md","filePath":"user/index.md","lastUpdated":1789105872000}'),e={name:"user/index.md"};function o(s,r,n,d,g,p){return l(),t("div",null,[...r[0]||(r[0]=[i('<h1 id="palleria-ユーザーガイド" tabindex="-1">Palleria ユーザーガイド <a class="header-anchor" href="#palleria-ユーザーガイド" aria-label="Permalink to &quot;Palleria ユーザーガイド&quot;">​</a></h1><p><strong>Palleria</strong> は、Android スマホ・タブレットで Pixiv（ピクシブ）の作品を快適に楽しむためのオープンソースアプリです。</p><p>イラスト、マンガ、小説の鑑賞から、作品のダウンロード、プライバシー保護、壁紙設定まで、豊富な機能をシンプルな操作で利用できます。</p><hr><h2 id="画面構成-5-つのメインタブ" tabindex="-1">画面構成 (5 つのメインタブ) <a class="header-anchor" href="#画面構成-5-つのメインタブ" aria-label="Permalink to &quot;画面構成 (5 つのメインタブ)&quot;">​</a></h2><p>画面下部のボトムナビゲーションバーから主要な画面にアクセスできます。</p><ul><li><strong>ホーム</strong>: 「おすすめ」作品と「フォロー中」絵師さんの最新タイムライン。</li><li><strong>検索 / ショート</strong>: タグ・キーワード検索。設定で縦スワイプ観賞フィードに変更可能。</li><li><strong>ブックマーク</strong>: 保存した公開・非公開作品のコレクション。</li><li><strong>ランキング</strong>: 今日の人気作品、週間・月間、R-18 ランキングなど。</li><li><strong>その他</strong>: 設定、閲覧履歴、ダウンロード一覧、オフラインライブラリなど。</li></ul><div class="tip custom-block"><p class="custom-block-title">小説を読むには</p><p>小説作品（一覧・ランキング・本文リーダー）は、画面右上にある <strong>「小説ボタン」</strong> をタップして開きます。</p></div><hr><h2 id="palleria-でできること" tabindex="-1">Palleria でできること <a class="header-anchor" href="#palleria-でできること" aria-label="Permalink to &quot;Palleria でできること&quot;">​</a></h2><ul><li><strong>イラスト・マンガ・小説の閲覧</strong>: 作品をスムーズに表示。マンガの見開き表示や、小説の「縦書き」表示にも対応しています。</li><li><strong>うごイラ（動くイラスト）の再生</strong>: 動くイラストをその場で再生・一時停止・保存できます。</li><li><strong>高機能な検索</strong>: タグ検索や作品名検索はもちろん、ブックマーク数での絞り込みや「お気に入りタグ（ウォッチリスト）」管理ができます。</li><li><strong>画像の保存・一括ダウンロード</strong>: 作品を原寸画質で端末に保存できます。作者ごと・作品ごとにフォルダを自動で分けることも可能です。</li><li><strong>安心のプライバシー保護</strong>: アプリに PIN ロックや指紋認証をかけられるほか、電卓画面になりすます「電卓偽装機能」を搭載しています。</li><li><strong>ライブ壁紙 &amp; ウィジェット</strong>: お気に入りのイラストをスマホの壁紙として自動切り替え表示したり、ホーム画面にランキングを表示できます。</li></ul><hr><h2 id="動作要件" tabindex="-1">動作要件 <a class="header-anchor" href="#動作要件" aria-label="Permalink to &quot;動作要件&quot;">​</a></h2><ul><li><strong>対応端末</strong>: Android 7.1 以上</li><li><strong>アカウント</strong>: Pixiv アカウント</li><li><strong>費用</strong>: 完全無料（広告なし・オープンソース）</li></ul>',14)])])}const u=a(e,[["render",o]]);export{h as __pageData,u as default};
